public class DiagnosticFilter implements Filter {
    private static final Logger log = LoggerFactory.getLogger(DiagnosticFilter.class);

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        long start = System.currentTimeMillis();
        try {
            // Pass request down the NIO/Servlet chain
            chain.doFilter(request, response);
        } catch (Exception ex) {
            log.error("Unhandled exception caught during request processing: URI={}", 
                ((HttpServletRequest) request).getRequestURI(), ex);
            throw ex;
        } finally {
            long duration = System.currentTimeMillis() - start;
            if (duration > 1000) {
                log.warn("SLOW API DETECTED: URI={} took {} ms", 
                    ((HttpServletRequest) request).getRequestURI(), duration);
            }
        }
    }
}
